/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ViewLookupStepState, ViewSearchText, ViewLookupStep, ViewTrackTitleSearch, ViewLookupTimeline
 *   Functions: catalogReviewLookupTimeline
 *   Constants: LOOKUP_TIMELINE_LIMITS
 * Internal
 *   Functions: isRecord, list, count, instant, fields, titleSearch, musicBrainzExhausted, trackTitleSearchView
 * @end-catalog */

/**
 * An existing-Album review run's timeline, as its lookup view shows it (lookupView.ts): the run's planned title searches, its
 * Track-title searches and its stages (release details, the iTunes fallback, its MusicBrainz bridge and the alias lookups) as
 * bounded steps with their states and counts; the texts those searches sent, each shown only when it is the review's own
 * (catalogReviewSearchTexts) or, for an answered bridge search, a title a shown candidate already carries; the derived state of the
 * Track-title searches; the stored automatic retry with its attempt; and the run's times. Built from stored fields only: a
 * respelled fallback search, whose sending the record does not keep, is not listed, and no count is added to the record. Some ends
 * of a run move `queryIndex` past searches it may never have sent: the candidate bound, MusicBrainz's retries running out (in any
 * phase, which moves it past the plan), a Track-title search the source did not answer, and a run that ended while it sent its
 * Track titles. Where the record shows that one may have happened (a partial search in a plan with Track titles, or in one without
 * them once MusicBrainz's retries ran out, the bound, MusicBrainz exhausted while searching, or the end), each search it cannot
 * vouch for is `unconfirmed`, never `done`. Which Track titles go alone, and which are then passed over, mirrors proceedLookupRun
 * (lookupRunStep.ts); the two change together. Pure and total on another release's stored shape. A run with nothing to search has
 * no timeline.
 */
import type { AdminImportDocument } from '../import/adminImportService';
import { METADATA_LOOKUP_JOB_LIMITS } from './lookupContract';
import { storedItunesStage } from './lookupItunesStage';
import { isFallbackLookupQuery, isTrackTitleLookupQuery } from './lookupQueryPlanner';
import { catalogReviewSearchTexts, catalogReviewTrackTitleSkip, comparableSearchText } from './lookupReviewEvidence';
import { trackTitleWeight, UNCREDITED_TRACK_TITLE_MIN_WEIGHT, type TrackTitleSkip } from './lookupTrackTitles';
import { isBlockingLookupState } from './metadataLookupRecord';

/** `unconfirmed`: a search past `queryIndex` that the record cannot vouch was sent. */
export type ViewLookupStepState = 'done' | 'unconfirmed' | 'active' | 'pending' | 'skipped';
/** One searched text and the Artist name its search was credited to, each at most 200 characters. */
export type ViewSearchText = { text: string; artist?: string };
/**
 * One step. A title search (`albumArtist`, `album`, `songArtist`, `song`) carries its one text; the Track-title step its titles;
 * `details`, `itunes`, `bridge` and `aliases` their settled and total requests (`done` at most `total`, both within 100), the
 * bridge also the answered searches' titles a shown candidate carries. The Track titles sent for certain and those that may not
 * have been sent are two `trackTitle` steps.
 */
export type ViewLookupStep = { kind: 'albumArtist' | 'album' | 'songArtist' | 'song' | 'trackTitle' | 'details' | 'itunes' | 'bridge' | 'aliases';
    state: ViewLookupStepState; done?: number; total?: number; texts?: ViewSearchText[] };
/**
 * The run's Track-title searches: sent, not needed (the title searches preselected or matched), not yet decided, or skipped
 * because no title could be searched (the picker's reason) or MusicBrainz stayed unavailable.
 */
export type ViewTrackTitleSearch = { state: 'sent' | 'notNeeded' | 'pending' } | { state: 'skipped'; reason: TrackTitleSkip | 'unavailable' };
/**
 * A review run's timeline: at most 12 steps in the order a run takes them (title searches, Track titles, release details, iTunes,
 * bridge, aliases), the Track-title search state where one can be said, the run's start, last-step and end times, and while it
 * waits for an automatic retry, when, for which source, and which retry of how many it is.
 */
export type ViewLookupTimeline = { steps: ViewLookupStep[]; trackTitleSearch?: ViewTrackTitleSearch; startedAt: string; updatedAt: string; completedAt: string | null;
    retry: { at: string; source: 'musicbrainz' | 'itunes'; attempt: number; limit: number } | null };

/** Steps, title-search steps (the planned-query bound), texts per step, characters per text and the bound of a step's counts. */
export const LOOKUP_TIMELINE_LIMITS = Object.freeze({ steps: 12, searches: 6, texts: 4, text: 200, count: 100 });
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const count = (value: unknown): number | null => Number.isSafeInteger(value) && (value as number) >= 0 ? value as number : null;
/** A stored time as an ISO string within the years 0000-9999, else null (as lookupView.ts reads its times). */
const instant = (value: unknown): string | null => value instanceof Date && Number.isFinite(value.getTime()) && /^\d{4}-/.test(value.toISOString()) ? value.toISOString() : null;
/** A planned search's query fields, or an empty record. */
const fields = (query: unknown): Record<string, unknown> => isRecord(query) && isRecord(query.query) ? query.query : {};
/** A title search of the plan: a release search by Album text or a recording search by song text, never a fallback. */
const titleSearch = (query: unknown) => isRecord(query) && !isFallbackLookupQuery(query) && isRecord(query.query)
    && ((query.kind === 'musicBrainzReleaseSearch' && query.basis === 'albumText') || (query.kind === 'musicBrainzRecordingSearch' && query.basis === 'songText'));

/** Whether MusicBrainz's automatic retries ran out during the run. */
const musicBrainzExhausted = (raw: Record<string, unknown>) => isRecord(raw.exhausted) && (raw.exhausted.musicbrainz === 'sourceBusy' || raw.exhausted.musicbrainz === 'sourceUnavailable');

/** The Track-title search state: from the stored decision while the plan holds such searches, else why none was planned. */
function trackTitleSearchView(raw: Record<string, unknown>, doc: AdminImportDocument, queries: readonly unknown[]): ViewTrackTitleSearch | null {
    if (queries.some(isTrackTitleLookupQuery)) {
        if (raw.trackTitleSearch === 'sent') return { state: 'sent' };
        if (raw.trackTitleSearch !== 'skipped') return { state: 'pending' };
        return musicBrainzExhausted(raw) ? { state: 'skipped', reason: 'unavailable' } : { state: 'notNeeded' };
    }
    const reason = catalogReviewTrackTitleSkip(doc, raw.input);
    return reason ? { state: 'skipped', reason } : null;
}

/**
 * The timeline of a review's stored run, or null when its start or last-step time is unreadable or it planned no search.
 * `candidateTitles` are the titles the view shows, which a bridge search's title must equal to be shown.
 */
export function catalogReviewLookupTimeline(raw: Record<string, unknown>, doc: AdminImportDocument, candidateTitles: readonly (string | null)[]): ViewLookupTimeline | null {
    const startedAt = instant(raw.createdAt), updatedAt = instant(raw.updatedAt), queries = list(raw.queries);
    // A run with nothing to search completed at once, and its status says why.
    if (!startedAt || !updatedAt || !queries.length) return null;
    const active = isBlockingLookupState(raw.state), running = active && raw.state !== 'queued', complete = raw.state === 'complete', phase = raw.phase;
    const first = queries.findIndex(isTrackTitleLookupQuery), at = count(raw.queryIndex) ?? 0, candidates = list(raw.candidates);
    const stage = storedItunesStage(raw.itunesStage);
    // MusicBrainz's retries ran out while it searched (the run ended there, or its iTunes stage started from it): the record keeps
    // neither which title search failed nor which were never sent.
    const exhausted = musicBrainzExhausted(raw) && (phase === 'search' || stage?.reason === 'searchUnavailable');
    // A partial search may be the candidate bound, which leaves the title searches it had not reached unsent: past the title
    // searches of a plan with Track titles (the bound moves `queryIndex` to them), and in a plan without them once MusicBrainz's
    // retries ran out in any phase (which moves `queryIndex` past the plan). Only the first search is then certain.
    const partial = raw.searchComplete !== true && (first >= 0 ? at >= first : musicBrainzExhausted(raw));
    const allowed = catalogReviewSearchTexts(doc, raw.input);
    const shown = (value: unknown): string | null => typeof value === 'string' && value.length <= LOOKUP_TIMELINE_LIMITS.text && allowed.has(comparableSearchText(value) ?? '') ? value : null;
    /** A search's text and credited Artist, or null unless both (an Artist only where the search names one) are shown. */
    const entry = (query: Record<string, unknown>, field: 'release' | 'recording'): ViewSearchText | null => {
        const text = shown(query[field]), artist = query.artist === undefined ? undefined : shown(query.artist);
        return text === null || artist === null ? null : { text, ...(artist ? { artist } : {}) };
    };
    const steps: ViewLookupStep[] = [];
    // Title searches before the Track-title tail: sent below `queryIndex` (unconfirmed where the run may have stopped short of
    // them), the one at it sending, later ones waiting, and once the search phase is over, one never reached (the candidate bound
    // ended the searches) skipped.
    (first >= 0 ? queries.slice(0, first) : queries).forEach((query, index) => {
        if (!titleSearch(query) || steps.length >= LOOKUP_TIMELINE_LIMITS.searches) return;
        const values = fields(query), release = (query as Record<string, unknown>).kind === 'musicBrainzReleaseSearch', credited = typeof values.artist === 'string';
        const text = entry(values, release ? 'release' : 'recording');
        const state: ViewLookupStepState = raw.state === 'queued' ? 'pending' : running && phase === 'search' && index === at ? 'active'
            : index < at ? exhausted || (partial && index > 0) ? 'unconfirmed' : 'done' : phase === 'search' && !complete ? 'pending' : 'skipped';
        steps.push({ kind: release ? credited ? 'albumArtist' : 'album' : credited ? 'songArtist' : 'song', state, ...(text ? { texts: [text] } : {}) });
    });
    const decision = trackTitleSearchView(raw, doc, queries);
    if (decision) {
        // Once sent, they went alone, without their planned Artist, when the credited title searches returned no release, and a light
        // title was then passed over; while undecided they show as planned.
        const alone = decision.state === 'sent' && first > 0 && queries.slice(0, first).some(query => typeof fields(query).artist === 'string') && raw.creditFound !== true;
        const planned = decision.state === 'sent' || decision.state === 'pending' ? queries.flatMap((query, index) => index >= first && isTrackTitleLookupQuery(query)
            ? [{ index, query: alone ? { recording: query.query.recording } : query.query }] : [])
            .filter(({ query }) => query.artist !== undefined || trackTitleWeight(query.recording) >= UNCREDITED_TRACK_TITLE_MIN_WEIGHT) : [];
        const texts = (from: typeof planned) => from.map(({ query }) => entry(query, 'recording')).filter((text): text is ViewSearchText => text !== null).slice(0, LOOKUP_TIMELINE_LIMITS.texts);
        const state: ViewLookupStepState = decision.state === 'sent' ? running && phase === 'search' && at >= first ? 'active' : 'done' : decision.state === 'pending' ? 'pending' : 'skipped';
        // Sent for certain: every title, unless the run may have stopped short of some. One that ended while sending them sent those
        // below `queryIndex`; at its candidate bound or after a partial search (one the source did not answer ends them), only the first.
        const sure = state !== 'done' ? planned.length : phase === 'search' && at < queries.length ? planned.filter(({ index }) => index < at).length
            : candidates.length >= METADATA_LOOKUP_JOB_LIMITS.candidates || raw.searchComplete !== true ? Math.min(planned.length, 1) : planned.length;
        const certain = texts(planned.slice(0, sure)), unsure = texts(planned.slice(sure));
        if (sure || !planned.length) steps.push({ kind: 'trackTitle', state, ...(certain.length ? { texts: certain } : {}) });
        if (planned.length > sure) steps.push({ kind: 'trackTitle', state: 'unconfirmed', ...(unsure.length ? { texts: unsure } : {}) });
    }
    const bounded = (done: number, total: number) => { const bound = Math.min(total, LOOKUP_TIMELINE_LIMITS.count); return { done: Math.min(done, bound), total: bound }; };
    /** A stage's state: active while the run is in its phase, done once settled, skipped when a completed run never needed it. */
    const stageState = (name: string, done: number, total: number): ViewLookupStepState =>
        raw.state === 'queued' ? 'pending' : running && phase === name ? 'active' : total && done >= total ? 'done' : total ? 'pending' : complete ? 'skipped' : 'pending';
    const settled = candidates.filter(candidate => isRecord(candidate) && candidate.details !== 'pending').length;
    steps.push({ kind: 'details', state: stageState('details', settled, candidates.length), ...(candidates.length ? bounded(settled, candidates.length) : {}) });
    if (stage) {
        steps.push({ kind: 'itunes', state: running && phase === 'itunes' ? 'active' : stage.state === 'unavailable' ? 'skipped' : stage.requestIndex >= stage.requests.length ? 'done' : 'pending',
            ...(stage.state === 'unavailable' ? {} : bounded(stage.requestIndex, stage.requests.length)) });
        // Only an answered bridge search names its title: one left unsent when MusicBrainz's retries ran out checked nothing.
        const bridge = stage.bridge, titles = new Set(candidateTitles.map(comparableSearchText).filter(Boolean));
        const texts = [...new Set((bridge ?? []).filter((_query, index) => stage.bridgeOutcomes[index] === 'found' || stage.bridgeOutcomes[index] === 'none')
            .map(query => fields(query)).map(values => values.release ?? values.recording)
            .filter((value): value is string => typeof value === 'string' && value.length <= LOOKUP_TIMELINE_LIMITS.text && titles.has(comparableSearchText(value))))]
            .slice(0, LOOKUP_TIMELINE_LIMITS.texts).map(text => ({ text }));
        steps.push({ kind: 'bridge', state: bridge === null ? complete ? 'skipped' : 'pending' : !bridge.length ? 'skipped' : running && phase === 'bridge' ? 'active'
            : stage.bridgeIndex >= bridge.length ? 'done' : 'pending', ...(bridge?.length ? bounded(stage.bridgeIndex, bridge.length) : {}), ...(texts.length ? { texts } : {}) });
    } else {
        // Without a stage a completed run did not need the fallback (or had no iTunes request); any other run has not reached it.
        steps.push({ kind: 'itunes', state: complete ? 'skipped' : 'pending' });
        if (!complete) steps.push({ kind: 'bridge', state: 'pending' });
    }
    const aliases = list(raw.aliases).filter(isRecord), fetched = aliases.filter(alias => alias.state !== 'pending').length;
    steps.push({ kind: 'aliases', state: stageState('aliases', fetched, aliases.length), ...(aliases.length ? bounded(fetched, aliases.length) : {}) });
    const retryAt = raw.state === 'retrying' ? instant(raw.retryAt) : null, source = phase === 'itunes' ? 'itunes' : 'musicbrainz';
    const attempt = isRecord(raw.attempts) ? count(raw.attempts[source]) : null, limit = METADATA_LOOKUP_JOB_LIMITS.retryDelaysMs.length;
    const completedAt = raw.completedAt === null || raw.completedAt === undefined ? null : instant(raw.completedAt);
    return { steps: steps.slice(0, LOOKUP_TIMELINE_LIMITS.steps), ...(decision ? { trackTitleSearch: decision } : {}), startedAt, updatedAt, completedAt,
        retry: retryAt && attempt !== null && attempt >= 1 && attempt <= limit ? { at: retryAt, source, attempt, limit } : null };
}
